fn max_width(rows: List[List[String]]) -> Int {
  let mut widths = List[Int]()
  for row in rows {
    for (i, cell) in enumerate(row) {
      if i >= widths.len() || str_len(cell) > widths[i] {
        widths = widths.append(str_len(cell))
      }
    }
  }
  return widths
}

fn align_columns(rows: List[List[String]]) -> List[String] {
  let widths = max_width(rows)
  return rows.map(|row| {
    row.map(|cell| cell + repeat(" ", widths[enumerate(row).0] - str_len(cell))).join(" | ")
  }).map(|row| trim(row))
}

