type BankOp =
  | Open(name: String)
  | Deposit(name: String, amount: Int)
  | Withdraw(name: String, amount: Int)
  | Transfer(src: String, dst: String, amount: Int)

fn bank_ledger(ops: List[BankOp]) -> Result[List[(String, Int)], String] {
  var accounts: Map[String, Int] = map_from([])
  var step = 1

  for op in ops {
    match op {
      Open(name) => {
        if map_get(accounts, name) != null {
          return Err(format("step {}: duplicate account {}", step, name))
        }
        map_set(accounts, name, 0)
      },
      Deposit(name, amount) => {
        if amount <= 0 {
          return Err(format("step {}: invalid amount", step))
        }
        var balance = map_get(accounts, name)
        if balance == null {
          return Err(format("step {}: unknown account {}", step, name))
        }
        map_set(accounts, name, balance + amount)
      },
      Withdraw(name, amount) => {
        if amount <= 0 {
          return Err(format("step {}: invalid amount", step))
        }
        var balance = map_get(accounts, name)
        if balance == null {
          return Err(format("step {}: unknown account {}", step, name))
        }
        if balance < amount {
          return Err(format("step {}: insufficient funds", step))
        }
        map_set(accounts, name, balance - amount)
      },
      Transfer(src, dst, amount) => {
        if amount <= 0 {
          return Err(format("step {}: invalid amount", step))
        }
        if src == dst {
          return Err(format("step {}: same account", step))
        }
        var src_balance = map_get(accounts, src)
        if src_balance == null {
          return Err(format("step {}: unknown account {}", step, src))
        }
        if src_balance < amount {
          return Err(format("step {}: insufficient funds", step))
        }
        var dst_balance = map_get(accounts, dst)
        if dst_balance == null {
          return Err(format("step {}: unknown account {}", step, dst))
        }
        map_set(accounts, src, src_balance - amount)
        map_set(accounts, dst, dst_balance + amount)
      },
    }
    step = step + 1
  }

  return Ok(map_to_list(accounts))
}

