fn parse_money(s: String) -> Result[Int, String] {
  let parts = s.split("$").collect::<Vec<&str>>();
  if parts.len() != 2 {
    return Err("missing $".to_string());
  }
  let (sign, dollars) = if parts[0].is_empty() {
    ("", parts[1])
  } else if parts[0] == "-" {
    ("-", parts[1])
  } else {
    return Err("missing $".to_string());
  };
  let cents = if let Some(dot) = dollars.find('.') {
    let cents_str = &dollars[dot + 1..];
    if cents_str.len() != 2 {
      return Err("bad cents".to_string());
    }
    cents_str.parse::<Int>().map_err(|_| "bad cents".to_string())?
  } else {
    0
  };
  let dollars = dollars.trim_end_matches('.').replace(",", "");
  if dollars.starts_with('0') && dollars.len() > 1 {
    return Err("bad dollars".to_string());
  }
  let dollars = dollars.parse::<Int>().map_err(|_| "bad dollars".to_string())?;
  Ok(if sign == "-" { -dollars * 100 - cents } else { dollars * 100 + cents })
}

