type OrderEvent =
  | Create(id: String)
  | Pay(id: String)
  | Ship(id: String)
  | Cancel(id: String)

type OrderState = {
  id: String,
  state: String,
}

fn order_states(events: List[OrderEvent]) -> Result[List[(String, String)], String] {
  var orders: Map[String, OrderState] = map_from([])

  for event in events {
    match event {
      Create(id) => {
        if map_get(orders, id) != null {
          return Err("duplicate order: " + id)
        }
        map_set(orders, id, { id: id, state: "created" })
      },
      Pay(id) => {
        var order = map_get(orders, id)
        if order == null {
          return Err("unknown order: " + id)
        }
        if order.state != "created" {
          return Err("cannot pay " + id + " from " + order.state)
        }
        map_set(orders, id, { id: id, state: "paid" })
      },
      Ship(id) => {
        var order = map_get(orders, id)
        if order == null {
          return Err("unknown order: " + id)
        }
        if order.state != "paid" {
          return Err("cannot ship " + id + " from " + order.state)
        }
        map_set(orders, id, { id: id, state: "shipped" })
      },
      Cancel(id) => {
        var order = map_get(orders, id)
        if order == null {
          return Err("unknown order: " + id)
        }
        if order.state != "created" && order.state != "paid" {
          return Err("cannot cancel " + id + " from " + order.state)
        }
        map_set(orders, id, { id: id, state: "cancelled" })
      },
    }
  }

  return Ok(map_to_list(orders, |order| (order.id, order.state)))
}

