  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  let by_dept = group_by(emps, |e| e.dept);
  let mut results = map_from([]);

  for (dept, es) in by_dept {
    let mut total = 0;
    for e in es {
      let regular = min(e.hours, 40) * e.rate_cents;
      let overtime = max(e.hours - 40, 0) * e.rate_cents * 3 / 2;
      total = total + regular + overtime;
    }
    map_set(results, dept, total);
  }

  let mut items = map_to_list(results);
  items = sort_by(items, |(d1, p1), (d2, p2)| {
    if p1 != p2 {
      p2 - p1
    } else {
      str_compare(d1, d2)
    }
  });
  return items;
}

