type Rank = String
type Suit = String
type Card = (Rank, Suit)
type Hand = List[Card]

fn poker_hand(cards: Hand) -> String {
  if cards.len() != 5 {
    return "invalid"
  }
  let unique_cards = cards.filter(|c| cards.count(|x| x == c) == 1)
  if unique_cards.len() != 5 {
    return "invalid"
  }
  let ranks = unique_cards.map(|c| c.0)
  let suits = unique_cards.map(|c| c.1)
  if suits.len() == 1 {
    if is_straight(ranks) {
      return "straight flush"
    } else {
      return "flush"
    }
  }
  let rank_counts = ranks.group_by(|r| r).map(|r, cs| (r, cs.len()))
  if rank_counts.len() == 2 {
    let mut counts = rank_counts.map(|_, c| c)
    counts.sort()
    if counts[0] == 2 {
      return "full house"
    } else {
      return "two pair"
    }
  }
  if rank_counts.len() == 3 {
    let mut counts = rank_counts.map(|_, c| c)
    counts.sort()
    if counts[0] == 1 {
      return "three of a kind"
    } else {
      return "one pair"
    }
  }
  if is_straight(ranks) {
    return "straight"
  }
  return "high card"
}

fn is_straight(ranks: List[Rank]) -> Bool {
  let mut sorted_ranks = ranks.sort_by(|a, b| compare_ranks(a, b))
  if sorted_ranks[0] == "2" && sorted_ranks[1] == "3" && sorted_ranks[2] == "4" && sorted_ranks[3] == "5" && sorted_ranks[4] == "A" {
    sorted_ranks = ["A", "2", "3", "4", "5"].map(|r| r)
  }
  for i in range(0, 4) {
    if compare_ranks(sorted_ranks[i], sorted_ranks[i + 1]) != 1 {
      return false
    }
  }
  return true
}

fn compare_ranks(a: Rank, b: Rank) -> Int {
  let rank_values = "23456789TJQKA".to_string().enumerate().map(|(i, r)| (r, i)).to_map()
  return rank_values[a] - rank_values[b]
}

