fn sliding_window_max(xs: List[Int], k: Int) -> Result[List[Int], String] {
  if k < 1 {
    return Err("window must be positive".to_string());
  }
  if k > len(xs) {
    return Err("window larger than input".to_string());
  }
  var result = List[Int]{};
  for i in range(0, len(xs) - k + 1) {
    var window = slice(xs, i, i + k);
    var max_val = max(window);
    result = append(result, max_val);
  }
  return Ok(result);
}

fn slice(xs: List[Int], start: Int, end: Int) -> List[Int] {
  var result = List[Int]{};
  for i in range(start, end) {
    result = append(result, xs[i]);
  }
  return result;
}

fn max(xs: List[Int]) -> Int {
  var max_val = xs[0];
  for i in range(1, len(xs)) {
    if xs[i] > max_val {
      max_val = xs[i];
    }
  }
  return max_val;
}

